struct SoundSettings {
    @Clamped var volume: Int
    init(startingVolume: Int) {
        _volume = Clamped(wrappedValue: startingVolume)
    }
}
let settings = SoundSettings(startingVolume: 150)
print(settings.volume, settings.$volume)

Инициализация идёт через правило wrapper и сразу сохраняет признак ограничения.

